[ "$mon" -ge 1 ] && [ "$mon" -le 12 ] && [ "$day" -ge 1 ] && [ "$day" -le 31 ] || { echo "invalid date: $date" >&2; exit 2; }

arguments.new_string:
if ! [[ "$date" =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}$ ]]; then echo "bad date: $date (expected YYYY-MM-DD)" >&2; exit 2; fi
